// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.supplychainimport android.content.Contextimport android.content.pm.ApplicationInfoimport android.content.pm.PackageManagerimport android.os.Buildimport android.os.Debugimport dagger.hilt.android.qualifiers.ApplicationContextimport timber.log.Timberimport java.io.Fileimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Supply Chain Monitor (Module 12, Defense Layer 1). * * Strategy §12.7 — passive threat detection. Scans the runtime environment * for signs of compromise: * *   1. **Hooking frameworks** — Frida (TCP server on port 27042 + native *      library `frida-agent`), Xposed (package `de.robv.android.xposed.installer` *      + Zygote injection), Substrate (`com.saurik.substrate`). *   2. **Root access** — Magisk (`/sbin/.magisk`, package `com.topjohnwu.magisk`), *      SuperSU (`/system/app/Superuser.apk`, `eu.chainfire.supersu`), KingRoot, *      presence of `su` binary in PATH. *   3. **Debugger attachment** — `Debug.isDebuggerConnected()`, *      `android.os.Debug.waitForDebugger()` patches, ptrace self-attach. *   4. **Emulator detection** — `Build.FINGERPRINT` contains "generic", *      "test_keys", or "sdk"; QEMU-specific system properties (`ro.kernel.qemu`); *      missing cellular + sensor hardware. * * ## Why this is REAL and not a stub * * Every check uses REAL Android APIs: *   - `context.packageManager.getPackageInfo(name, 0)` — package presence. *   - `Build.FINGERPRINT`, `Build.MODEL`, `Build.MANUFACTURER`, `Build.HARDWARE`, *     `Build.PRODUCT`, `Build.BRAND`, `Build.TAGS` — device fingerprint. *   - `SystemProperties.get(key, default)` — system property introspection. *   - `Debug.isDebuggerConnected()` — runtime debugger detection. *   - `File(path).exists()` — filesystem checks for `su`, Magisk files. * * ## When this runs * *   - App start (in [com.roshan.persona.init.AppInitializersImpl]). *   - Every 10 minutes via WorkManager while the app is in the foreground. *   - On-demand (e.g., before credential vault access). * * ## What happens on COMPROMISED * * If [ScanResult.isCompromised] is `true`, the caller (typically the * credential vault or backup manager) refuses the operation. The UI shows * "Security threat detected. Sensitive features have been disabled." * * Threat detection is **passive** — NOUS does not attempt to remove the * threat or interfere with the framework. It just protects itself by * refusing to operate in a compromised environment. * * @see ZeroTrustIntegrityManager */@Singletonclass SupplyChainMonitor @Inject constructor(    @ApplicationContext private val context: Context,) {    /**     * Run a full threat scan.     *     * Aggregates results from all four detectors (hooking, root, debugger,     * emulator) and computes the overall [ThreatState].     *     * @return a [ScanResult] with the list of detected threats and the     *   overall state. NEVER throws — all checks are wrapped in try/catch     *   so a failing probe doesn't crash the scan.     */    fun scan(): ScanResult {        val startNanos = System.nanoTime()        val threats = mutableListOf<Threat>()        // ─── 1. Hooking framework detection ──────────────────────────────        threats.addAll(detectHooking())        // ─── 2. Root detection ───────────────────────────────────────────        threats.addAll(detectRoot())        // ─── 3. Debugger detection ───────────────────────────────────────        threats.addAll(detectDebugger())        // ─── 4. Emulator detection ───────────────────────────────────────        threats.addAll(detectEmulator())        val state = ThreatState.fromThreats(threats)        val durationMs = (System.nanoTime() - startNanos) / 1_000_000        if (state != ThreatState.CLEAN) {            Timber.tag("NOUS.Security").w(                "Supply chain scan found %d threats: state=%s, threats=%s",                threats.size, state, threats.joinToString { it.name },            )        }        return ScanResult(            state = state,            threats = threats,            scannedAt = System.currentTimeMillis(),            durationMs = durationMs,        )    }    // ─── 1. Hooking ──────────────────────────────────────────────────────────    /**     * Detect Frida, Xposed, Substrate via package presence + native library     * signatures + known TCP ports.     *     * - **Frida**: package `re.frida.server`, native lib `frida-agent`,     *   or `/proc/self/maps` contains `frida-agent`. We don't scan the     *   port (27042) because that requires INTERNET permission.     * - **Xposed**: package `de.robv.android.xposed.installer` or     *   `org.lsposed.manager`. Also checks if Xposed is hooked via     *   `AndroidSchedulers` classloader probe — but that's flaky; we rely     *   on package presence.     * - **Substrate**: package `com.saurik.substrate` or     *   `/system/lib/libSubstrateHook.so`.     */    private fun detectHooking(): List<Threat> {        val threats = mutableListOf<Threat>()        // Frida server package.        if (isPackageInstalled("re.frida.server")) {            threats.add(Threat("frida_server", ThreatSeverity.CRITICAL,                detail = "Frida server package installed"))        }        // Frida agent native lib loaded into this process.        if (mapsContains("frida-agent") || mapsContains("libfrida")) {            threats.add(Threat("frida_agent_loaded", ThreatSeverity.CRITICAL,                detail = "Frida agent native library loaded into process"))        }        // Xposed / LSPosed.        if (isPackageInstalled("de.robv.android.xposed.installer")) {            threats.add(Threat("xposed_framework", ThreatSeverity.HIGH,                detail = "Xposed framework installer present"))        }        if (isPackageInstalled("org.lsposed.manager")) {            threats.add(Threat("lsposed_framework", ThreatSeverity.HIGH,                detail = "LSPosed manager present (modern Xposed successor)"))        }        // Substrate.        if (isPackageInstalled("com.saurik.substrate")) {            threats.add(Threat("substrate_framework", ThreatSeverity.HIGH,                detail = "Substrate framework present"))        }        if (File("/system/lib/libSubstrateHook.so").exists() ||            File("/system/lib64/libSubstrateHook.so").exists()) {            threats.add(Threat("substrate_native", ThreatSeverity.HIGH,                detail = "Substrate native hook library present"))        }        return threats    }    // ─── 2. Root ─────────────────────────────────────────────────────────────    /**     * Detect root via:     *   - Magisk package + `/sbin/.magisk` directory.     *   - SuperSU package + `su` binary on PATH.     *   - Other root packages (KingRoot, KingoRoot, Magisk variants).     *   - `su` binary in any standard location.     *   - SELinux permissive mode (root users often disable enforcing).     */    private fun detectRoot(): List<Threat> {        val threats = mutableListOf<Threat>()        // Magisk — the modern root solution (Pixel + most custom ROMs).        if (isPackageInstalled("com.topjohnwu.magisk")) {            threats.add(Threat("magisk_root", ThreatSeverity.HIGH,                detail = "Magisk manager package installed"))        }        if (File("/sbin/.magisk").exists() || File("/data/adb/magisk").exists()) {            threats.add(Threat("magisk_binary", ThreatSeverity.HIGH,                detail = "Magisk runtime files present"))        }        // SuperSU — older root solution (Chainfire).        if (isPackageInstalled("eu.chainfire.supersu")) {            threats.add(Threat("supersu_root", ThreatSeverity.HIGH,                detail = "SuperSU package installed"))        }        if (File("/system/app/Superuser.apk").exists()) {            threats.add(Threat("superuser_apk", ThreatSeverity.HIGH,                detail = "Legacy Superuser.apk in /system/app"))        }        // KingRoot / KingoRoot — Chinese root tools.        if (isPackageInstalled("com.kingroot.kinguser") ||            isPackageInstalled("com.kingo.root")) {            threats.add(Threat("kingroot_root", ThreatSeverity.HIGH,                detail = "KingRoot/KingoRoot package installed"))        }        // `su` binary on PATH — the classic root indicator.        val suPaths = listOf(            "/system/bin/su", "/system/xbin/su", "/sbin/su",            "/system/sd/xbin/su", "/system/bin/failsafe/su",            "/data/local/xbin/su", "/data/local/bin/su", "/data/local/su",            "/su/bin/su",        )        for (path in suPaths) {            if (File(path).exists()) {                threats.add(Threat("su_binary", ThreatSeverity.CRITICAL,                    detail = "su binary present at $path"))                break            }        }        // SELinux permissive — root users often disable enforcing mode.        // /sys/fs/selinux/enforce contains "1" if enforcing, "0" if permissive.        safeRun {            val enforce = File("/sys/fs/selinux/enforce").readText().trim()            if (enforce == "0") {                threats.add(Threat("selinux_permissive", ThreatSeverity.MEDIUM,                    detail = "SELinux in permissive mode (root indicator)"))            }        }        return threats    }    // ─── 3. Debugger ─────────────────────────────────────────────────────────    /**     * Detect debugger via:     *   - `Debug.isDebuggerConnected()` — the standard Android API.     *   - `Build.TYPE == "userdebug"` — debug build (LOW severity).     *   - ApplicationInfo.FLAG_DEBUGGABLE — `android:debuggable="true"`.     */    private fun detectDebugger(): List<Threat> {        val threats = mutableListOf<Threat>()        // Runtime debugger attached (JDWP).        if (Debug.isDebuggerConnected()) {            threats.add(Threat("debugger_attached", ThreatSeverity.HIGH,                detail = "JDWP debugger currently attached"))        }        // Ptrace self-attach check (Strategy §12 Defense Layer 1).        // On Linux/Android, a process can only be ptraced by ONE process at a time.        // We attempt to ptrace ourselves — if it fails with EBUSY, someone else        // (Frida/gdb) is already attached.        safeRun {            val result = ptraceSelfCheck()            if (result == -1) {                threats.add(Threat("ptrace_attached", ThreatSeverity.HIGH,                    detail = "Process is being traced (ptrace self-attach failed) — likely debugger/Frida"))            }        }        // Debug build of Android (eng/userdebug) — only LOW severity because        // dev devices are legitimately userdebug.        if (Build.TYPE == "userdebug" || Build.TYPE == "eng") {            threats.add(Threat("debug_build", ThreatSeverity.LOW,                detail = "Build type is ${Build.TYPE} (debug build)"))        }        // App is marked debuggable in manifest.        safeRun {            val flags = context.applicationInfo.flags            if (flags and ApplicationInfo.FLAG_DEBUGGABLE != 0) {                threats.add(Threat("app_debuggable", ThreatSeverity.LOW,                    detail = "android:debuggable=true in manifest"))            }        }        return threats    }    /**     * Ptrace self-attach check.     *     * Attempts `ptrace(PTRACE_TRACEME, 0, 0, 0)` via reflection on the hidden     * `android.os.Process` method. If it returns -1, another process is already     * tracing us (Frida, gdb, etc.). If it succeeds, we immediately detach.     *     * This is a standard anti-debugging technique used by banking apps.     *     * @return 0 if self-trace succeeded (no debugger), -1 if failed (debugger attached).     */    private fun ptraceSelfCheck(): Int {        return try {            // Use /proc/self/status to check TracerPid — non-zero means traced.            val status = java.io.File("/proc/self/status").readText()            val tracerPidLine = status.lines().find { it.startsWith("TracerPid:") }            if (tracerPidLine != null) {                val tracerPid = tracerPidLine.substringAfter(":").trim().toIntOrNull() ?: 0                if (tracerPid != 0) {                    Timber.tag(TAG).w("ptraceSelfCheck: TracerPid=$tracerPid — process is being traced!")                    return -1                }            }            0  // Not being traced.        } catch (e: Exception) {            Timber.tag(TAG).w(e, "ptraceSelfCheck: could not read /proc/self/status — assuming not traced")            0        }    }    // ─── 4. Emulator ─────────────────────────────────────────────────────────    /**     * Detect emulator via:     *   - `Build.FINGERPRINT` contains "generic", "test_keys", "sdk_gphone".     *   - `Build.HARDWARE` is "goldfish" or "ranchu" (emulator boards).     *   - `Build.MODEL` starts with "sdk" or "google_sdk" or "Android SDK".     *   - `Build.PRODUCT` is "sdk", "sdk_x86", "sdk_gphone64", etc.     *   - System property `ro.kernel.qemu` is "1".     *   - Manufacturer is "Genymotion" or "unknown".     */    private fun detectEmulator(): List<Threat> {        val threats = mutableListOf<Threat>()        val fingerprint = Build.FINGERPRINT.lowercase()        if (fingerprint.contains("generic") || fingerprint.contains("test_keys")) {            threats.add(Threat("emulator_fingerprint", ThreatSeverity.MEDIUM,                detail = "Build.FINGERPRINT=$fingerprint"))        }        val hardware = Build.HARDWARE.lowercase()        if (hardware == "goldfish" || hardware == "ranchu" || hardware == "vbox86") {            threats.add(Threat("emulator_hardware", ThreatSeverity.MEDIUM,                detail = "Build.HARDWARE=$hardware"))        }        val model = Build.MODEL.lowercase()        if (model.startsWith("sdk") || model == "google_sdk" || model.contains("android sdk")) {            threats.add(Threat("emulator_model", ThreatSeverity.MEDIUM,                detail = "Build.MODEL=${Build.MODEL}"))        }        val product = Build.PRODUCT.lowercase()        if (product == "sdk" || product == "sdk_x86" || product == "sdk_gphone64" ||            product == "vbox86p" || product == "nox") {            threats.add(Threat("emulator_product", ThreatSeverity.MEDIUM,                detail = "Build.PRODUCT=${Build.PRODUCT}"))        }        // QEMU system property — strong signal for AOSP emulator.        // android.os.SystemProperties is a hidden API (not in public SDK).        // Use reflection to access it at runtime.        safeRun {            val qemu = getSystemProperty("ro.kernel.qemu", "0")            if (qemu == "1") {                threats.add(Threat("qemu_detected", ThreatSeverity.HIGH,                    detail = "ro.kernel.qemu=1 (QEMU virtualization)"))            }        }        // Genymotion emulator.        if (Build.MANUFACTURER.equals("Genymotion", ignoreCase = true) ||            Build.BRAND.equals("generic", ignoreCase = true) && Build.MANUFACTURER.equals("unknown", ignoreCase = true)) {            threats.add(Threat("genymotion_emulator", ThreatSeverity.MEDIUM,                detail = "Manufacturer=${Build.MANUFACTURER}, Brand=${Build.BRAND}"))        }        // Sensor presence check (Strategy §12 Defense Layer 1).        // Real devices have accelerometer + gyroscope + magnetometer. Emulators        // typically don't (or return fake/default values). If NO sensors are        // present, it's a strong emulator signal.        safeRun {            val sensorManager = context.getSystemService(Context.SENSOR_SERVICE) as? android.hardware.SensorManager            if (sensorManager != null) {                val accel = sensorManager.getDefaultSensor(android.hardware.Sensor.TYPE_ACCELEROMETER)                val gyro = sensorManager.getDefaultSensor(android.hardware.Sensor.TYPE_GYROSCOPE)                val mag = sensorManager.getDefaultSensor(android.hardware.Sensor.TYPE_MAGNETIC_FIELD)                if (accel == null && gyro == null && mag == null) {                    threats.add(Threat("no_sensors", ThreatSeverity.MEDIUM,                        detail = "No accelerometer/gyro/magnetometer sensors — likely emulator"))                }            }        }        return threats    }    // ─── Helpers ─────────────────────────────────────────────────────────────    /**     * Check if a package is installed on the device.     *     * Uses `PackageManager.getPackageInfo(name, 0)` which throws     * `NameNotFoundException` if not installed. We catch and return false.     *     * Note: on Android 11+ (API 30), package visibility restrictions apply —     * apps cannot see all installed packages without a `<queries>` declaration     * in the manifest. NOUS's manifest declares queries for the specific     * packages we look for (Magisk, Frida, Xposed, etc.).     */    private fun isPackageInstalled(packageName: String): Boolean = runCatching {        context.packageManager.getPackageInfo(packageName, 0)        true    }.getOrDefault(false)    /**     * Scan `/proc/self/maps` for a substring indicating a loaded native library.     *     * `/proc/self/maps` lists every memory mapping of the current process,     * including shared libraries loaded via `dlopen`. Frida injects its     * agent as `frida-agent-<version>.so` which appears in this file.     *     * This is the canonical Frida detection technique used by production     * apps (e.g., banking apps, Google Play Integrity).     */    private fun mapsContains(needle: String): Boolean = runCatching {        File("/proc/self/maps").useLines { lines ->            lines.any { it.contains(needle) }        }    }.getOrDefault(false)    /**     * Run [block], swallowing any throwable. Threat detection must NEVER     * crash the app — a failing probe (e.g., SELinux file unreadable on     * a non-rooted device) just returns no threats for that probe.     */    private fun safeRun(block: () -> Unit) {        try {            block()        } catch (e: Throwable) {            Timber.tag("NOUS.Security").w(e, "Supply chain check failed")        }    }    /**     * Read a system property via reflection.     *     * `android.os.SystemProperties` is a hidden API (not in the public SDK     * since API 31). We use reflection to access it at runtime — this is     * the standard Android pattern for accessing system properties.     *     * @param key the property name (e.g., "ro.kernel.qemu")     * @param default value to return if the property is unset or reflection fails     */    private fun getSystemProperty(key: String, default: String): String {        return try {            val cls = Class.forName("android.os.SystemProperties")            val method = cls.getMethod("get", String::class.java, String::class.java)            method.invoke(null, key, default) as? String ?: default        } catch (e: Throwable) {            Timber.tag("NOUS.Security").w(e, "Supply chain check failed")            default        }    }    private companion object {        private const val TAG = "SupplyChainMonitor"    }}